const std::array<glm::vec3, kColourMapEntries>& colour_map_table(ColourMapId id) {
    switch (id) {
        case ColourMapId::inferno:
            return kInferno;
        case ColourMapId::cool_warm:
            return kCoolWarm;
        case ColourMapId::viridis:
            break;
    }
    return kViridis;
}

